-- Fakt kartochkalarining ruscha matni — 29-partiya: davrlarga oid
-- umumiy kartochkalar (hero_id yo'q, era_id bor).
--
-- Bular oldingi partiyalarda tushib qolgan edi: barcha dumplar qahramon
-- slugi bo'yicha olingan, bu 64 ta kartochka esa hech bir qahramonga
-- bog'lanmagan. Shu migratsiya bilan 1522 ta kartochkaning hammasi
-- ruscha old tomonga ega bo'ladi.

-- ===== Qadimgi davr =====
UPDATE fact_cards SET topic_ru = 'Древнейшие стоянки', question_ru = 'Где найдены следы древнейших людей на территории Узбекистана?', fact_ru = 'В пещере Сельунгур в Ферганской долине древние люди жили почти миллион лет назад. А в пещере Тешик-Таш в Сурхандарье были найдены останки ребёнка-неандертальца — это открытие прославилось на весь мир.' WHERE id = 82;
UPDATE fact_cards SET topic_ru = '«Авеста»', question_ru = 'Что за книга «Авеста» и когда её начали создавать?', fact_ru = '«Авеста» — священная книга зороастризма, её начали создавать почти 2700 лет назад. Многие учёные считают, что древнейшие её части возникли в Хорезмском оазисе. В 2001 году 2700-летие «Авесты» широко отмечалось.' WHERE id = 83;
UPDATE fact_cards SET topic_ru = 'Первые государства', question_ru = 'Каковы древнейшие государства на нашей земле?', fact_ru = 'Древнейшие государства на нашей земле — Большой Хорезм, Бактрия и Согдиана. Они возникли в I тысячелетии до нашей эры: Бактрия — в верхнем течении Амударьи, Согдиана — в долине Зеравшана, Хорезм — в низовьях Амударьи.' WHERE id = 84;
UPDATE fact_cards SET topic_ru = 'Отвага Томирис', question_ru = 'Кем была Томирис и чем она прославилась?', fact_ru = 'Томирис — царица массагетов. Когда в VI веке до нашей эры персидский царь Кир II вторгся в землю массагетов, воины во главе с Томирис разгромили завоевателей. Её имя стало символом защиты Родины.' WHERE id = 85;
UPDATE fact_cards SET topic_ru = 'Отвага Ширака', question_ru = 'Кем был Ширак и какую отвагу он проявил?', fact_ru = 'Ширак — сакский пастух. Когда войско персидского царя Дария I вторглось в нашу страну, Ширак под видом проводника нарочно завёл вражеское войско в безводную пустыню и отдал жизнь за свою Родину.' WHERE id = 86;
UPDATE fact_cards SET topic_ru = 'Культура бронзового века', question_ru = 'Где найдены памятники бронзового века?', fact_ru = 'Памятники Сапаллитепа и Джаркутан в Сурхандарье относятся к бронзовому веку. Там во II тысячелетии до нашей эры земледелие, ремёсла и зодчество развились на высоком уровне — это образец первой градостроительной культуры нашего края.' WHERE id = 87;
UPDATE fact_cards SET topic_ru = 'Зороастризм', question_ru = 'Что считалось священным в зороастризме?', fact_ru = 'Зороастризм — древняя религия, основанная пророком Заратуштрой. В ней священными считались огонь, вода, земля и воздух, а главным правилом были благая мысль, благое слово и благое дело. Корни праздника Навруз тоже восходят к этой древней поре.' WHERE id = 88;
UPDATE fact_cards SET topic_ru = 'Крепости древнего Хорезма', question_ru = 'Какие крепости строились в древнем Хорезме?', fact_ru = 'В древнем Хорезме были построены огромные крепости — Топрак-кала, Аяз-кала, Джанбас-кала. Хорезмийцы возвели посреди пустыни сложные оросительные каналы и подняли земледелие на высокий уровень.' WHERE id = 89;

-- ===== Antik davr =====
UPDATE fact_cards SET topic_ru = 'Поход Александра', question_ru = 'Когда Александр Македонский вторгся в Мавераннахр?', fact_ru = 'Александр Македонский вторгся в Мавераннахр в 329 году до нашей эры. Наш народ во главе с согдийским полководцем Спитаменом три года оказывал завоевателям упорное сопротивление.' WHERE id = 90;
UPDATE fact_cards SET topic_ru = 'Греко-Бактрийское государство', question_ru = 'Когда образовалось Греко-Бактрийское государство?', fact_ru = 'В середине III века до нашей эры образовалось Греко-Бактрийское государство. В эту пору греческая и местная культуры соединились, и возникло своеобразное искусство — культура эллинизма.' WHERE id = 91;
UPDATE fact_cards SET topic_ru = 'Государство Канг', question_ru = 'Где располагалось государство Канг?', fact_ru = 'В III веке до нашей эры в среднем течении Сырдарьи возникло государство Канг (Кангюй). Оно было одним из могущественных государств своего времени и богатело земледелием, скотоводством и торговлей на Шёлковом пути.' WHERE id = 92;
UPDATE fact_cards SET topic_ru = 'Государство Даван', question_ru = 'Чем прославилось государство Даван?', fact_ru = 'В древности в Ферганской долине располагалось государство Даван. Оно прославилось породистыми конями, прозванными «небесными аргамаками», — китайские императоры даже устраивали военные походы, чтобы завладеть этими конями.' WHERE id = 93;
UPDATE fact_cards SET topic_ru = 'Кушанская держава', question_ru = 'Когда правила Кушанская держава?', fact_ru = 'В I–III веках нашей эры наша земля входила в состав могущественной Кушанской державы. При Канишке держава достигла наивысшей вершины; святилища Фаязтепа и Каратепа близ Термеза свидетельствуют о широком распространении буддизма.' WHERE id = 94;
UPDATE fact_cards SET topic_ru = 'Великий шёлковый путь', question_ru = 'Какие страны связывал Великий шёлковый путь?', fact_ru = 'Великий шёлковый путь связывал Китай со странами Средиземноморья и проходил через нашу страну. Караваны везли шёлк, пряности, стекло и драгоценные камни; вдоль пути расцветали города — Самарканд, Бухара, Термез.' WHERE id = 95;
UPDATE fact_cards SET topic_ru = 'Согдийские купцы', question_ru = 'Какое место занимали согдийские купцы на Шёлковом пути?', fact_ru = 'Согдийские купцы были главными посредниками Шёлкового пути. Они открыли торговые конторы от Китая до Византии, а согдийский язык стал языком международной торговли на этом пути.' WHERE id = 96;
UPDATE fact_cards SET topic_ru = 'Афрасиаб', question_ru = 'Что такое Афрасиаб и какие находки там сделаны?', fact_ru = 'Афрасиаб — место древнего Самарканда. На найденных там знаменитых стенных росписях изображены приём послов, праздничные обряды и одежды той поры — эти росписи редчайший свидетель городской культуры древности.' WHERE id = 97;

-- ===== Arab davri =====
UPDATE fact_cards SET topic_ru = 'Арабское завоевание', question_ru = 'Когда и под чьим началом арабы завоевали Мавераннахр?', fact_ru = 'Арабский полководец Кутайба ибн Муслим в 709–712 годах завоевал Бухару, Самарканд и Хорезм. Вместе с завоеванием пришли ислам и арабское письмо, глубоко повлиявшие на культуру края.' WHERE id = 98;
UPDATE fact_cards SET topic_ru = 'Восстание Муканны', question_ru = 'Когда и против чего поднялось восстание Муканны?', fact_ru = 'В 70-е годы VIII века восстание «людей в белом» во главе с Муканной поднялось против гнёта арабского халифата. Восстание длилось более десяти лет и стало символом народной борьбы за свободу.' WHERE id = 99;
UPDATE fact_cards SET topic_ru = 'Байт уль-хикма и наши учёные', question_ru = 'Что такое «Байт уль-хикма» и кто из наших земляков там работал?', fact_ru = 'В IX веке в багдадском «Байт уль-хикма» (Доме мудрости) учёные родом из Мавераннахра и Хорезма — аль-Хорезми и аль-Фергани — внесли огромный вклад в мировую науку. Аль-Хорезми положил начало алгебре, а его имя навеки осталось в слове «алгоритм».' WHERE id = 100;
UPDATE fact_cards SET topic_ru = 'Ахмад аль-Фергани', question_ru = 'Каким учёным был Ахмад аль-Фергани?', fact_ru = 'Ахмад аль-Фергани — великий астроном. Его книга «Основы астрономии» веками была учебником в Европе под именем «Альфраганус». Он также спроектировал в Египте знаменитое сооружение для измерения уровня воды в Ниле — ниломер.' WHERE id = 101;
UPDATE fact_cards SET topic_ru = 'Султаны науки хадисов', question_ru = 'Какие великие учёные науки хадисов вышли из нашей страны?', fact_ru = 'Наши земляки Имам аль-Бухари и Имам ат-Термизи считаются величайшими учёными науки хадисов. Сборник аль-Бухари «Аль-джами ас-сахих» признан в исламском мире самой достоверной книгой после Корана.' WHERE id = 102;
UPDATE fact_cards SET topic_ru = 'Государство Саманидов', question_ru = 'Какой город был столицей государства Саманидов?', fact_ru = 'В IX–X веках Бухара, столица государства Саманидов, стала крупным центром науки и культуры. В эту пору возродилась местная государственность, расцвели персидско-таджикская литература (Рудаки) и наука.' WHERE id = 103;
UPDATE fact_cards SET topic_ru = 'Ибн Сина и Беруни', question_ru = 'Какой вклад внесли Ибн Сина и Беруни в мировую науку?', fact_ru = 'X–XI века — пора учёных-энциклопедистов: Ибн Сина «Каноном врачебной науки» положил начало мировой медицине, а Абу Райхан Беруни в трудах «Индия» и «Памятники минувших поколений» обогатил историю, географию и астрономию.' WHERE id = 104;
UPDATE fact_cards SET topic_ru = 'Абу Наср Фараби', question_ru = 'Почему Абу Насра Фараби называют «Вторым учителем»?', fact_ru = 'Абу Наср Фараби был возвеличен как «Второй учитель» (после Аристотеля) за огромный вклад в философию, логику и науку о музыке. Его труд «Город добродетельных людей» выражает мечты о справедливом обществе.' WHERE id = 105;

-- ===== Temuriylar davri =====
UPDATE fact_cards SET topic_ru = 'Централизованное государство', question_ru = 'Когда и кем было основано централизованное государство в Мавераннахре?', fact_ru = 'В 1370 году Амир Темур основал в Мавераннахре централизованное государство. Его девиз «Сила — в справедливости» был главным правилом управления державой, а в «Уложении Темура» изложены законы и правила этого управления.' WHERE id = 106;
UPDATE fact_cards SET topic_ru = 'Столица Самарканд', question_ru = 'В какой город превратил Самарканд Амир Темур?', fact_ru = 'Амир Темур стремился превратить Самарканд в прекраснейший город мира: в эту пору поднялись соборная мечеть Биби-ханым, мавзолей Гур-Эмир и ансамбль Шахи-Зинда. А в Шахрисабзе был построен величественный Ак-Сарай.' WHERE id = 107;
UPDATE fact_cards SET topic_ru = 'Обсерватория Улугбека', question_ru = 'Когда была построена обсерватория Улугбека и какой труд там был создан?', fact_ru = 'Мирзо Улугбек в 1428–1429 годах построил в Самарканде огромную обсерваторию. В составленной там таблице «Зидж-и джадид-и Гурагани» положение 1018 звёзд указано с изумительной точностью — этот труд издавался и в Европе.' WHERE id = 108;
UPDATE fact_cards SET topic_ru = 'Медресе Улугбека', question_ru = 'В каких городах Улугбек построил медресе?', fact_ru = 'Улугбек построил медресе в Самарканде, Бухаре и Гиждуване. На вратах бухарского медресе начертано изречение «Получение знания — долг каждого мусульманина и каждой мусульманки» — это символ высокого почтения к науке.' WHERE id = 109;
UPDATE fact_cards SET topic_ru = 'Навои и родной язык', question_ru = 'Что сделал Алишер Навои для тюркского языка?', fact_ru = 'Алишер Навои трудами «Хамса» и «Хазойин уль-маони» превратил тюркский (староузбекский) язык в язык великой литературы. В труде «Мухокамат уль-лугатайн» он доказал богатство нашего родного языка, сравнив его с персидским.' WHERE id = 110;
UPDATE fact_cards SET topic_ru = 'Герат — центр культуры', question_ru = 'Почему Герат конца XV века считался культурной столицей Востока?', fact_ru = 'В конце XV века Герат под правлением Хусейна Байкары стал культурной столицей Востока: здесь творил Навои, а Камалиддин Бехзад поднял искусство миниатюры так высоко, что его прозвали «Рафаэлем Востока».' WHERE id = 111;
UPDATE fact_cards SET topic_ru = 'Восточное Возрождение', question_ru = 'Почему пору Тимуридов называют «Восточным Возрождением»?', fact_ru = 'Пору Тимуридов называют «Восточным Возрождением» (Ренессансом Тимуридов): астрономия, математика, история, литература, каллиграфия и зодчество развились небывало и внесли огромный вклад в мировую культуру.' WHERE id = 112;
UPDATE fact_cards SET topic_ru = 'Бабур и Бабуриды', question_ru = 'Какой державе положил начало Бабур в Индии?', fact_ru = 'Тимуридский царевич Захириддин Мухаммад Бабур в 1526 году положил начало державе Бабуридов в Индии. Его труд «Бабурнаме» — первые мемуары на нашем родном языке, а построенный Бабуридами Тадж-Махал — жемчужина мирового зодчества.' WHERE id = 113;

-- ===== Xonliklar davri =====
UPDATE fact_cards SET topic_ru = 'Пора Шейбанидов', question_ru = 'Когда Шейбаниды взяли власть в Мавераннахре?', fact_ru = 'В 1500–1506 годах Мухаммад Шейбанихан овладел державой Тимуридов и утвердил в Мавераннахре правление династии Шейбанидов. В XVI веке Бухарское ханство стало крупным государством области.' WHERE id = 114;
UPDATE fact_cards SET topic_ru = 'Три государства', question_ru = 'Какие три государства были на нашей земле в XVIII–XIX веках?', fact_ru = 'В XVIII–XIX веках на нашей земле существовали три государства: Бухарский эмират, Хивинское ханство и Кокандское ханство. Частые войны между ними ослабили край и подготовили почву для иноземного завоевания.' WHERE id = 115;
UPDATE fact_cards SET topic_ru = 'Хан-историк Абулгази', question_ru = 'Какой труд написал Абулгази Бахадурхан?', fact_ru = 'Хивинский хан Абулгази Бахадурхан (1603–1664) был не только государственным деятелем, но и учёным: его труд «Шаджарайи турк» считается важным источником в изучении истории тюркских народов.' WHERE id = 116;
UPDATE fact_cards SET topic_ru = 'Ичан-кала', question_ru = 'Чем редкостен хивинский комплекс Ичан-кала?', fact_ru = 'Хивинский комплекс Ичан-кала — редкостный город-памятник, где минареты, медресе и дворцы сохранились как единое целое. Он первым в Узбекистане был внесён в список Всемирного наследия ЮНЕСКО.' WHERE id = 117;
UPDATE fact_cards SET topic_ru = 'Зодчество Бухары', question_ru = 'Какие здания были построены в Бухаре в пору ханств?', fact_ru = 'В пору ханств в Бухаре были построены ансамбль Ляби-хауз, Чор-Минор и множество торговых куполов. А минарет Калян, стоящий с XII века, стал символом города.' WHERE id = 118;
UPDATE fact_cards SET topic_ru = 'Классическая литература', question_ru = 'Какие поэты творили в пору ханств?', fact_ru = 'В пору ханств нашу классическую литературу обогатили Бабарахим Машраб, воспевавший народное горе, творившие в Хорезме Мунис и Агахи, а в Коканде — Амирий и Фуркат.' WHERE id = 119;
UPDATE fact_cards SET topic_ru = 'Поэтессы', question_ru = 'Кто были знаменитые поэтессы поры ханств?', fact_ru = 'Надира, супруга кокандского хана Умархана, и её современница Увайси — великие поэтессы узбекской классической литературы. Надира деятельно участвовала и в государственных делах, была покровительницей культуры.' WHERE id = 120;
UPDATE fact_cards SET topic_ru = 'Ремёсла и торговля', question_ru = 'Какие ремесленные школы сложились в пору ханств?', fact_ru = 'В пору ханств сложились такие ремесленные школы, как маргиланский атлас, риштанская керамика, бухарское золотое шитьё. Базары и караван-сараи были средоточием городской жизни.' WHERE id = 121;

-- ===== Jadidlar davri =====
UPDATE fact_cards SET topic_ru = 'Российское завоевание', question_ru = 'Когда Ташкент был занят Российской империей?', fact_ru = 'В 1865 году Ташкент был занят Российской империей, а в 1867 году образовано Туркестанское генерал-губернаторство. Бухарский эмират и Хивинское ханство были превращены в зависимые от России государства.' WHERE id = 122;
UPDATE fact_cards SET topic_ru = 'Движение джадидов', question_ru = 'На что было направлено движение джадидов?', fact_ru = 'Джадидизм («джадид» — новый) — движение, направленное на то, чтобы в условиях колониального гнёта пробудить нацию через просвещение. Джадиды стремились дать народу знания через школы нового метода, печать и театр.' WHERE id = 123;
UPDATE fact_cards SET topic_ru = 'Школы нового метода', question_ru = 'Чем школы нового метода отличались от старой школы?', fact_ru = 'В школах усули джадид дети выучивались грамоте гораздо быстрее, чем по старому способу, — за несколько месяцев, и осваивали также светские науки: географию, счёт и историю. Эти школы стали колыбелью национального пробуждения.' WHERE id = 124;
UPDATE fact_cards SET topic_ru = 'Махмудходжа Бехбуди', question_ru = 'Чем прославился Махмудходжа Бехбуди?', fact_ru = 'Самаркандец Махмудходжа Бехбуди — вождь джадидов, автор первой узбекской драмы «Отцеубийца» и издатель журнала «Ойна». Он остался в истории со своими знаменитыми словами: «Право берут, а не дают!»' WHERE id = 125;
UPDATE fact_cards SET topic_ru = 'Мунавваркари и Авлони', question_ru = 'Что сделали Мунавваркари Абдурашидханов и Абдулла Авлони?', fact_ru = 'В Ташкенте Мунавваркари Абдурашидханов создал сеть школ нового метода и написал учебник «Адиби аввал». А Абдулла Авлони распространял просвещение книгой «Тюркский цветник, или нравственность» и театральной труппой.' WHERE id = 126;
UPDATE fact_cards SET topic_ru = 'Национальная печать', question_ru = 'Когда начали выходить первые узбекские газеты?', fact_ru = 'В 1906 году начала выходить одна из первых узбекских газет — «Тараккий». Позже издания «Садои Туркистон», «Самарканд» и другие доносили до народа мировые события и растили национальное самосознание.' WHERE id = 127;
UPDATE fact_cards SET topic_ru = 'Фитрат и Чулпан', question_ru = 'Какие произведения написали Фитрат и Чулпан?', fact_ru = 'Абдурауф Фитрат в труде «Спор» проводил идеи преобразования общества, а Абдулхамид Чулпан романом «Ночь и день» и стихами о свободе положил начало новой узбекской литературе.' WHERE id = 128;
UPDATE fact_cards SET topic_ru = 'Наследие джадидов', question_ru = 'Какова была главная мысль джадидов?', fact_ru = 'Джадиды видели будущее нации в образованном поколении: «Спасение — в образовании» было их главной мыслью. Их отвага на пути просвещения высоко ценится в сегодняшнем независимом Узбекистане.' WHERE id = 129;

