UPDATE fact_cards SET topic_ru = 'Туркестанская автономия', question_ru = 'Когда и где была провозглашена Туркестанская автономия?', fact_ru = 'В ноябре 1917 года в Коканде была провозглашена Туркестанская автономия — это была первая попытка нашего народа возродить собственную государственность. Автономия прожила всего 72 дня и была потоплена в крови советскими войсками.' WHERE id = 130;
UPDATE fact_cards SET topic_ru = 'Узбекская ССР', question_ru = 'Когда была образована Узбекская ССР?', fact_ru = 'В итоге национально-территориального размежевания 1924 года была образована Узбекская ССР. Столицей сперва был Самарканд, а в 1930 году она была перенесена в Ташкент.' WHERE id = 131;
UPDATE fact_cards SET topic_ru = 'Жертвы репрессий', question_ru = 'Какие сыны нации погибли в репрессиях 1937–1938 годов?', fact_ru = 'В репрессиях 1937–1938 годов были расстреляны самые яркие сыны нации — Абдулла Кадыри, Чулпан, Фитрат и тысячи наших земляков. Их память чтят 31 августа — в День памяти жертв репрессий.' WHERE id = 132;
UPDATE fact_cards SET topic_ru = 'Узбекистан в годы войны', question_ru = 'Какой вклад внёс Узбекистан в годы Второй мировой войны?', fact_ru = 'Во Второй мировой войне на фронт было мобилизовано более 1,5 миллиона жителей Узбекистана, сотни тысяч наших земляков погибли. В Узбекистан были эвакуированы сотни заводов и тысячи детей-сирот — семья Шамахмудовых приняла в свои объятия 15 сирот.' WHERE id = 133;
UPDATE fact_cards SET topic_ru = 'Хлопковая монокультура и Арал', question_ru = 'К каким последствиям привела хлопковая монокультура?', fact_ru = 'В советскую пору сельское хозяйство Узбекистана было подчинено хлопковой монокультуре. Оттого что воды Амударьи и Сырдарьи были отведены на поля, Аральское море начало высыхать — это одна из крупнейших экологических трагедий XX века.' WHERE id = 134;
UPDATE fact_cards SET topic_ru = 'Ташкентское землетрясение', question_ru = 'Когда произошло Ташкентское землетрясение?', fact_ru = '26 апреля 1966 года в Ташкенте произошло сильное землетрясение, сотни тысяч людей остались без крова. Город был отстроен заново в короткий срок: возникли современные широкие улицы и новые жилые массивы.' WHERE id = 135;
UPDATE fact_cards SET topic_ru = 'Литература XX века', question_ru = 'Какие узбекские писатели творили в XX веке?', fact_ru = 'Несмотря на тяжкие испытания, в XX веке узбекская культура развивалась: Айбек создал роман «Навои», Гафур Гулям — «Озорника», а поэзия Зульфии нашла место в сердцах миллионов читателей.' WHERE id = 136;
UPDATE fact_cards SET topic_ru = 'К независимости', question_ru = 'Когда узбекскому языку был дан статус государственного?', fact_ru = '21 октября 1989 года узбекскому языку был дан статус государственного — это был важный шаг на пути к независимости. К августу 1991 года Узбекистан был готов провозгласить свою независимость.' WHERE id = 137;

