UPDATE fact_cards SET topic_ru = 'Провозглашение независимости', question_ru = 'Когда была провозглашена государственная независимость Узбекистана?', fact_ru = '31 августа 1991 года была провозглашена государственная независимость Узбекистана; 1 сентября отмечается как День независимости. С этого началась новая пора в истории нашего народа.' WHERE id = 138;
UPDATE fact_cards SET topic_ru = 'Конституция', question_ru = 'Когда была принята Конституция Республики Узбекистан?', fact_ru = '8 декабря 1992 года была принята Конституция Республики Узбекистан. В ней права человека, свобода слова и верховенство закона определены как высшие ценности государства.' WHERE id = 139;
UPDATE fact_cards SET topic_ru = 'Государственные символы', question_ru = 'Когда были приняты государственный флаг, герб и гимн?', fact_ru = 'Государственный флаг принят 18 ноября 1991 года, герб — 2 июля 1992 года, гимн — 10 декабря 1992 года. В середине герба изображена легендарная птица Хумо — символ счастья и свободы.' WHERE id = 140;
UPDATE fact_cards SET topic_ru = 'Цвета флага', question_ru = 'Что означают цвета нашего флага?', fact_ru = 'На нашем флаге голубой цвет — символ неба и воды, белый — мира и чистоты, зелёный — природы и обновления; красные полосы означают силу жизни. А полумесяц и 12 звёзд связаны с древними календарными традициями нашего народа.' WHERE id = 141;
UPDATE fact_cards SET topic_ru = 'В мировом сообществе', question_ru = 'Когда Узбекистан стал членом Организации Объединённых Наций?', fact_ru = '2 марта 1992 года Узбекистан стал членом Организации Объединённых Наций. Сегодня нашу страну признали почти все государства мира, и она деятельно участвует в международных организациях.' WHERE id = 142;
UPDATE fact_cards SET topic_ru = 'Национальная валюта', question_ru = 'Когда была введена в обращение наша национальная валюта — сум?', fact_ru = '1 июля 1994 года наша национальная валюта — сум — была введена в обращение. Иметь собственные деньги — один из важных признаков государственной независимости.' WHERE id = 143;
UPDATE fact_cards SET topic_ru = 'Возрождение ценностей', question_ru = 'Какие ценности были возрождены в годы независимости?', fact_ru = 'В годы независимости был возрождён праздник Навруз, обрело почёт наследие Амира Темура, Улугбека и Бабуридов: 1996 год был объявлен «Годом Амира Темура», и 660-летие сахибкирана широко отмечалось.' WHERE id = 144;
UPDATE fact_cards SET topic_ru = 'Всемирное наследие', question_ru = 'Какие исторические центры Узбекистана внесены в список ЮНЕСКО?', fact_ru = 'В годы независимости исторические центры Ичан-калы, Бухары, Шахрисабза и Самарканда были внесены в список Всемирного наследия ЮНЕСКО — богатства, созданные нашими предками, теперь считаются достоянием всего человечества.' WHERE id = 145;
